pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the desired new owner address; the current caller will be the contract deployer by default in setUp,
    // but we use vm.prank to call as that owner. The general rule: when the owner calls setOwner(newOwner),
