import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: newOwner (the address passed to setOwner) and caller (the account that invokes setOwner)
    function testFuzz_property(address newOwner, address caller) public {
        // keep addresses in wide admissible domain but avoid zero address for clarity
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // ensure the contract's current owner is the deployer (setUp used test contract deployer),
        // so we must act as that owner to call setOwner: the test contract is the deployer of c
        // but here we want an external EOA caller to be the owner who invokes setOwner.
        // To create that scenario, first transfer ownership to `caller` from the current owner (this test contract).

        // current owner is address(this) (the test contract) because setUp deployed c from this contract
        // call setOwner to make `caller` the owner
        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // this must succeed on reference contract; if it failed something is wrong with environment
        assertTrue(ok);

        // Now act as `caller` to call setOwner with argument newOwner
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after a call to setOwner(newOwner) by the current owner (caller),
        // the contract's owner getter must equal the provided newOwner argument.
        // This holds for the reference; the mutant that assigns owner = msg.sender will make owner==caller
        // and thus fail whenever caller != newOwner. The single assertion below observes c.owner().
        assertTrue(c.owner() == newOwner);
    }
}

