import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller who will attempt to set a new owner, and the candidate new owner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but not the zero-address for clarity
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure the contract's deployer (setUp) is the starting owner
        address initialOwner = c.owner();

        // The property we assert: if the current owner calls setOwner(newOwner) then owner() equals newOwner
        // We must exercise the scenario by having the actual current owner (initialOwner) call setOwner.
        // The fuzzed inputs are caller and newOwner; to make the fuzzer search for a distinguishing input,
        // we will try to let caller be the one who performs the call. We only perform the call when caller == initialOwner,
        // otherwise the call would be expected to revert and not helpful for the universal property. This keeps the domain wide
        // while allowing the fuzzer to pick caller == initialOwner to trigger the decisive behavior.

        // Only perform the owner-invoked update when the fuzzed caller equals the current owner
        if (caller == initialOwner) {
            // perform the call as the owner
            vm.prank(caller);
            bool ok;
            try c.setOwner(newOwner) returns (bool r) {
                ok = r;
            } catch {
                ok = false;
            }
            // If the correct contract: the owner call should succeed and owner() == newOwner for ALL such inputs.
            // The mutant will make the owner call revert (or fail) because it requires msg.sender != owner.
            // Assert the universal property by checking the resulting owner equals newOwner.
            assertTrue(ok && c.owner() == newOwner);
        } else {
            // When caller is not the current owner, we don't perform the privileged call; still assert the universal
            // property vacuously by checking that owner remains the initial owner (no change performed here).
            assertTrue(c.owner() == initialOwner);
        }
    }
}

