pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    AttackerHelper helper;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker address (an EOA) and a newOwner to set
    function testFuzz_property(address attackerEOA, address newOwner) public {
        // keep addresses non-zero to be meaningful
        vm.assume(attackerEOA != address(0));
        vm.assume(newOwner != address(0));
        // deploy a helper contract that will call c on behalf of attackerEOA
        helper = new AttackerHelper(c);

        // Fund attacker EOA so it can send txs
        vm.deal(attackerEOA, 1 ether);

        // The rule: only msg.sender == owner can change owner in the reference.
        // Setup: ensure the owner is the test contract deployer (setUp did that).
        address originalOwner = c.owner();

        // Sanity: originalOwner should be this contract (setUp deployed c from this contract)
        // Now have an EOA (attackerEOA) send a tx that calls the helper which forwards the call to c.
        // In the reference, only msg.sender (the helper contract) is checked, so helper != owner and
        // setOwner should revert / be disallowed; in the mutant that checks tx.origin it compares
        // tx.origin (attackerEOA) to owner and may allow the change if attackerEOA == owner.

        // Ensure attackerEOA is not equal to originalOwner to allow triggering difference when needed
        vm.assume(attackerEOA != originalOwner);

        // From attackerEOA, call helper which will in turn call c.setOwner(newOwner)
        vm.prank(attackerEOA);
        helper.callSetOwner(newOwner);

        // The universal property we assert: after the above interaction, in the correct contract
        // the owner must still be originalOwner (a non-owner external EOA calling via a contract
        // must not change owner). The mutant that checks tx.origin can allow the change for some
        // attackerEOA/newOwner choices, so this assertion will fail on the mutant for some fuzz inputs.
        assertTrue(c.owner() == originalOwner);
    }
}

// Helper contract that forwards the call, so msg.sender != tx.origin when c is invoked
contract AttackerHelper {
    C immutable target;
    constructor(C _target) { target = _target; }
    function callSetOwner(address _owner) external {
        // forward the call to target; in the callee, msg.sender == address(this) and tx.origin == original EOA
        target.setOwner(_owner);
    }
}

