import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (the tx origin / EOA) and newOwner (the address to attempt to set)
    // We keep domain wide but avoid trivial equality that would make the test inconclusive.
    function testFuzz_property(address txOrigin, address newOwner) public {
        // Keep inputs wide but require txOrigin != address(0) to be a sensible EOA
        vm.assume(txOrigin != address(0));
        // Deploy an intermediate caller contract that will call C.setOwner on behalf of txOrigin
        // This models an adversary: tx.origin == txOrigin, but msg.sender == address(intermediate)
        Caller intermediary = new Caller(address(c));

        // Fund the txOrigin so it can call the intermediary
        vm.deal(txOrigin, 1 ether);

        // Ensure the initial owner is the test deployer (setUp's deployer)
        address initialOwner = c.owner();
        // For the reference property to be meaningful, if txOrigin is NOT equal to initialOwner,
        // then a call routed through the intermediary must NOT change owner (since msg.sender != owner)
        // We therefore restrict to the case where txOrigin != initialOwner to create adversarial attempt
        vm.assume(txOrigin != initialOwner);

        // Have txOrigin call the intermediary which in turn calls c.setOwner(newOwner)
        vm.prank(txOrigin);
        intermediary.callSetOwner(newOwner);

        // Exactly one assertion: reference enforces that owner remains unchanged for this scenario
        // (because msg.sender will be intermediary, not the owner). The mutant using tx.origin would
        // allow the change when txOrigin == owner, but we ensured txOrigin != initialOwner so the
        // mutant can be exploited to change owner while the reference cannot.
        assertTrue(c.owner() == initialOwner);
    }
}

// Minimal intermediary contract that simply forwards a call to C.setOwner
contract Caller {
    C target;
    constructor(address _target) { target = C(_target); }
    function callSetOwner(address _owner) external {
        // forward the call; msg.sender here is this contract, tx.origin is the original EOA
        target.setOwner(_owner);
    }
}

