pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address that will act as the attacker intermediary, and a candidate newOwner
    function testFuzz_property(address intermediary, address candidateNewOwner) public {
        // keep addresses non-zero and distinct from contract address to avoid trivialities
        vm.assume(intermediary != address(0));
        vm.assume(candidateNewOwner != address(0));
        vm.assume(intermediary != address(c));
        vm.assume(candidateNewOwner != address(c));

        // Deploy a minimal intermediary adversary that will call c.setOwner(candidateNewOwner)
        // when its forwardCall is invoked. This models an external contract intermediary so
        // tx.origin differs from msg.sender inside C when intermediary calls C.
        Intermediary adv = new Intermediary(c);

        // The reference contract sets owner to deployer in setUp(); that deployer is address(this)
        // so address(this) is the initial owner. We will have address(this) invoke adv.forwardCall
        // but adv will be the immediate msg.sender when calling c.setOwner, so for the reference
        // (which checks msg.sender == owner) the call must fail; for the mutant (which checks tx.origin)
        // the call may succeed because tx.origin == address(this).

        // Ensure the fuzzer does not pick the intermediary equal to this test contract
        vm.assume(address(adv) != address(this));

        // As the initial owner (this contract), call the intermediary which then calls c.setOwner
        // trying to set owner to candidateNewOwner. We capture whether the call to setOwner succeeded
        // by having adv.forwardCall return true/false.
        bool ok = adv.tryForward(candidateNewOwner);

        // The universal property for the reference: setOwner should only succeed when msg.sender == owner.
        // Because adv will be the immediate caller (msg.sender inside C) and adv != owner (owner is address(this)),
        // the reference must make the call fail for ALL admissible inputs. Therefore ok must be false for ALL inputs.
        // The mutant that checks tx.origin instead will see tx.origin == address(this) and may allow the change,
        // making ok == true for some inputs; thus this assertion distinguishes them.
        assertTrue(!ok);
    }
}

// Minimal intermediary that forwards a call to C.setOwner and reports whether it succeeded.
contract Intermediary {
    C immutable target;
    constructor(C _target) { target = _target; }

    // Try to forward a call to target.setOwner(newOwner). Return true if the call succeeded, false if it reverted.
    function tryForward(address newOwner) external returns (bool) {
        try target.setOwner(newOwner) {
            return true;
        } catch {
            return false;
        }
    }
}

